-- Catalog-only current production policy definitions, applied ONLY to fake DB.
alter table public."monthly_overrides" enable row level security;
do $$declare p record;begin for p in select policyname from pg_policies where schemaname='public' and tablename='monthly_overrides' loop execute format('drop policy %I on public.%I',p.policyname,'monthly_overrides');end loop;end$$;
create policy "monthly_overrides: authenticated delete" on public."monthly_overrides" as PERMISSIVE for DELETE to "authenticated" using ((((household_id IS NULL) AND (user_id = ( SELECT auth.uid() AS uid))) OR ((household_id IS NOT NULL) AND ( SELECT private.is_household_editor(monthly_overrides.household_id) AS is_household_editor))));
create policy "monthly_overrides: authenticated insert" on public."monthly_overrides" as PERMISSIVE for INSERT to "authenticated" with check ((((household_id IS NULL) AND (user_id = ( SELECT auth.uid() AS uid))) OR ((household_id IS NOT NULL) AND ( SELECT private.is_household_editor(monthly_overrides.household_id) AS is_household_editor))));
create policy "monthly_overrides: authenticated read" on public."monthly_overrides" as PERMISSIVE for SELECT to "authenticated" using ((((household_id IS NULL) AND (user_id = ( SELECT auth.uid() AS uid))) OR ((household_id IS NOT NULL) AND ( SELECT private.is_household_member(monthly_overrides.household_id) AS is_household_member))));
create policy "monthly_overrides: authenticated update" on public."monthly_overrides" as PERMISSIVE for UPDATE to "authenticated" using ((((household_id IS NULL) AND (user_id = ( SELECT auth.uid() AS uid))) OR ((household_id IS NOT NULL) AND ( SELECT private.is_household_editor(monthly_overrides.household_id) AS is_household_editor)))) with check ((((household_id IS NULL) AND (user_id = ( SELECT auth.uid() AS uid))) OR ((household_id IS NOT NULL) AND ( SELECT private.is_household_editor(monthly_overrides.household_id) AS is_household_editor))));
